            {{- assistant_token + think_begin_token }}
        {%- elif reasoning_effort is defined and reasoning_effort == 'no_think' %}
            {{- assistant_token + think_begin_token + think_end_token }}
        {%- else %}
            {{- assistant_token }}
        {%- endif %}
    {%- endif %}
{%- endif %}

